   "fecha": "2026-11-24T10:44:10Z",
   "tipo": "comercial",
   "genero": "noticia",
   "imagen": "https://gestion.pe/resizer/v2/BBXSXSJ7KJFL5MCIH6L42YSYBI.jpg?auth=4957239b249bc279e68928edf4d0ac0fd8ece3376fbc46319bf6e9340823b045&smart=true&width=1200&height=800",
